(function () {
  var footerNote = document.querySelector('[data-gc-sp-footer-note]');
  var previewBtn = document.getElementById('gc-sp-go-preview');
  var reasonEl = document.getElementById('gc-sp-footer-reason');
  var toastEl = document.querySelector('[data-gc-draft-toast]');
  var READY_NOTE = '本页只写入草稿；「确认发布」在「规则版本」页，须经「发布前预览」做冲突校验后确认。';

  // 一个事件同一时刻只对应一个网格责任人：责任人空缺的网格（如 G-0421）会让匹配失败无从派发
  function unassignedGrids() {
    var out = [];
    [].slice.call(document.querySelectorAll('td[data-cell="owner"][data-grid]')).forEach(function (td) {
      var stChip = td.closest('tr').querySelector('.gc-chip');
      if (stChip && stChip.classList.contains('gc-chip--off')) return; // 停用网格不参与派发，不阻断
      var v = (td.textContent || '').replace(/\s/g, '');
      if (!v || v === '—' || v.indexOf('（空）') >= 0 || v.indexOf('(空)') >= 0) {
        out.push(td.getAttribute('data-grid'));
      }
    });
    return out;
  }

  // 责任人补齐后，把该行状态从「待定责」同步为「启用」，避免状态与责任人自相矛盾
  function syncStatusChips() {
    [].slice.call(document.querySelectorAll('td[data-cell="owner"][data-grid]')).forEach(function (td) {
      var v = (td.textContent || '').replace(/\s/g, '');
      var filled = !!v && v !== '—' && v.indexOf('（空）') < 0 && v.indexOf('(空)') < 0;
      if (!filled) return;
      var tr = td.closest('tr');
      var chip = tr && tr.querySelector('.gc-chip--muted');
      if (chip && (chip.textContent || '').indexOf('待定责') >= 0) {
        chip.className = 'gc-chip gc-chip--green';
        chip.textContent = '启用';
        var tbtn = tr.querySelector('[data-gc-toggle]');
        if (tbtn) tbtn.textContent = '停用';
      }
    });
  }

  function scanConflicts() {
    syncStatusChips();
    var voids = unassignedGrids();
    var blocked = voids.length > 0;
    if (footerNote) {
      footerNote.textContent = blocked
        ? '不能进入发布前预览：仍有网格没有责任人（' + voids.join('、') + '），事件匹配到这些网格后无法派发。'
        : READY_NOTE;
      footerNote.classList.toggle('gc-shell-footer-note--block', blocked);
    }
    if (previewBtn) {
      previewBtn.disabled = blocked;
      var tip = blocked ? '仍有网格未定责（' + voids.join('、') + '），不能进入发布前预览' : '带着本草稿进入发布前预览';
      previewBtn.title = tip;
      if (reasonEl) reasonEl.textContent = tip;
    }
    document.body.setAttribute('data-gc-draft-state', blocked ? 'blocked' : 'ready');
    return voids;
  }

  // ── 底部动作条：只写入草稿 / 进入发布前预览（发布不在模块页） ──
  var saveDraft = document.querySelector('[data-gc-sp-save-draft]');
  if (saveDraft) saveDraft.addEventListener('click', function () {
    toast('已写入草稿，尚未生效。发布需在「规则版本」页经「发布前预览」做冲突校验后确认。');
  });
  if (previewBtn) previewBtn.addEventListener('click', function () {
    if (previewBtn.disabled) return;
    location.href = 'publish-preview.html?scene=ok';
  });
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add('gc-draft-toast--show');
    clearTimeout(toast._t);
    toast._t = setTimeout(function () { toastEl.classList.remove('gc-draft-toast--show'); }, 3200);
  }

  // ── 责任人或新增网格保存后复检（本脚本的委托监听晚于 space-edit-js 的行内监听） ──
  document.addEventListener('click', function () { scanConflicts(); });
  scanConflicts();
})();

